use anyhow::{Context,Result}; use clap::{Parser,Subcommand}; use scratchpad_core::*; use std::{io::Read,path::PathBuf}; use tokio::{io::{AsyncBufReadExt,AsyncWriteExt,BufReader},net::UnixStream}; use uuid::Uuid;
#[derive(Parser)] #[command(name="scratchpad")] struct Cli{#[command(subcommand)]cmd:Cmd}
#[derive(Subcommand)] enum Cmd{Ping,List{#[arg(default_value_t=100)]limit:usize},Show{id:Uuid},Remove{id:Uuid},Pages,NewPage{name:String},Page{id:Uuid},AddText{#[arg(long)]stdin:bool,text:Vec<String>},AddUrl{url:String},AddPath{path:PathBuf}}
#[tokio::main] async fn main()->Result<()> { let c=Cli::parse(); let req=match c.cmd {Cmd::Ping=>Request::Ping,Cmd::List{limit}=>Request::ListObjects{limit},Cmd::Show{id}=>Request::GetObject{object_id:id},Cmd::Remove{id}=>Request::RemoveObject{object_id:id},Cmd::Pages=>Request::ListPages,Cmd::NewPage{name}=>Request::CreatePage{name},Cmd::Page{id}=>Request::GetPage{page_id:id},Cmd::AddText{stdin,text}=>{let s=if stdin{let mut x=String::new();std::io::stdin().read_to_string(&mut x)?;x}else{text.join(" ")};let o=Object::new(ObjectKind::Text,first_line(&s),SourceDescriptor::Cli).with_representation("text/plain;charset=utf-8",RepresentationRole::Primary,StorageRef::InlineText{text:s.clone()},Some(s.len() as u64));Request::AddObject{object:o,page_id:None,placement:None}},Cmd::AddUrl{url}=>{url::Url::parse(&url).context("invalid URL")?;let o=Object::new(ObjectKind::Url,Some(url.clone()),SourceDescriptor::Cli).with_representation("text/uri-list",RepresentationRole::Primary,StorageRef::Uri{uri:url.clone()},Some(url.len() as u64)).with_representation("text/plain;charset=utf-8",RepresentationRole::Secondary,StorageRef::InlineText{text:url.clone()},Some(url.len() as u64));Request::AddObject{object:o,page_id:None,placement:None}},Cmd::AddPath{path}=>{let p=std::fs::canonicalize(&path).with_context(||format!("cannot access {}",path.display()))?;let md=std::fs::metadata(&p)?;let kind=if md.is_dir(){ObjectKind::Directory}else{kind_for_path(&p)};let mime=if md.is_dir(){"inode/directory".into()}else{mime_for_path(&p)};let o=Object::new(kind,p.file_name().map(|x|x.to_string_lossy().into_owned()),SourceDescriptor::FileSystem{path:p.display().to_string()}).with_representation(mime,RepresentationRole::Primary,StorageRef::ExternalPath{path:p.display().to_string()},Some(md.len()));Request::AddObject{object:o,page_id:None,placement:None}}}; let resp=send(req).await?; println!("{}",serde_json::to_string_pretty(&resp)?); Ok(()) }
async fn send(req:Request)->Result<Response>{let p=Paths::discover();let mut s=UnixStream::connect(&p.socket).await.with_context(||format!("connect {} (is scratchpad-daemon running?)",p.socket.display()))?;let env=RequestEnvelope::new(req);s.write_all(serde_json::to_string(&env)?.as_bytes()).await?;s.write_all(b"\n").await?;let mut line=String::new();BufReader::new(s).read_line(&mut line).await?;Ok(serde_json::from_str::<ResponseEnvelope>(&line)?.response)}
fn first_line(s:&str)->Option<String>{s.lines().next().map(|x|x.chars().take(80).collect())}
fn kind_for_path(p:&std::path::Path)->ObjectKind{match p.extension().and_then(|x|x.to_str()).unwrap_or("").to_ascii_lowercase().as_str(){"png"|"jpg"|"jpeg"|"webp"|"gif"=>ObjectKind::Image,"mp4"|"mkv"|"webm"|"mov"=>ObjectKind::Video,"mp3"|"flac"|"wav"|"ogg"=>ObjectKind::Audio,"pdf"=>ObjectKind::Pdf,_=>ObjectKind::File}}
fn mime_for_path(p:&std::path::Path)->String{match kind_for_path(p){ObjectKind::Image=>"image/*",ObjectKind::Video=>"video/*",ObjectKind::Audio=>"audio/*",ObjectKind::Pdf=>"application/pdf",_=>"application/octet-stream"}.into()}
